const inputOriginal = $input.first().json;

// Aceita dados achatados ou vindos diretamente do Webhook em body
const input = inputOriginal.body ?? inputOriginal;

function cleanText(value) {
  if (value === undefined || value === null) return '';
  return String(value).replace(/^=/, '').trim();
}

function extractDateBR(text) {
  const match = String(text || '').match(/(\d{2})\/(\d{2})\/(\d{4})/);

  if (!match) return null;

  const [, dd, mm, yyyy] = match;
  return `${yyyy}-${mm}-${dd}`;
}

function formatDate(value) {
  if (!value) {
    return new Date().toISOString().slice(0, 10);
  }

  const cleaned = cleanText(value);

  if (/^\d{4}-\d{2}-\d{2}$/.test(cleaned)) {
    return cleaned;
  }

  const date = new Date(cleaned);

  if (!isNaN(date.getTime())) {
    return date.toISOString().slice(0, 10);
  }

  return new Date().toISOString().slice(0, 10);
}

function toList(value) {
  if (value === undefined || value === null || value === '') return [];

  if (Array.isArray(value)) {
    return value.map(cleanText).filter(Boolean);
  }

  if (typeof value === 'object') {
    if (Array.isArray(value.itens)) {
      return value.itens.map(cleanText).filter(Boolean);
    }

    return [JSON.stringify(value)];
  }

  const text = cleanText(value);

  if (!text) return [];

  try {
    const parsed = JSON.parse(text);

    if (Array.isArray(parsed)) {
      return parsed.map(cleanText).filter(Boolean);
    }

    if (parsed && typeof parsed === 'object' && Array.isArray(parsed.itens)) {
      return parsed.itens.map(cleanText).filter(Boolean);
    }

    return [cleanText(parsed)].filter(Boolean);
  } catch (error) {
    return text
      .split(/;|\n/)
      .map(v => cleanText(v))
      .filter(Boolean);
  }
}

const obra_codigo = cleanText(input.obra_codigo) || null;
const responsavel = cleanText(input.responsavel) || null;

const clima = cleanText(input.clima) || null;
const condicoes_canteiro = cleanText(input.condicoes_canteiro) || 'Não informado.';

const atividades = toList(input.atividades);
const maoDeObra = toList(input.mao_de_obra);
const equipamentos = toList(input.equipamentos);
const materiais = toList(input.materiais);
const ocorrencias = toList(input.ocorrencias);
let pendencias = toList(input.pendencias);

// Texto geral usado para detectar data e pendências
const textoGeralOriginal = [
  cleanText(input.mensagem),
  cleanText(input.atividades),
  cleanText(input.ocorrencias),
  cleanText(input.pendencias),
  atividades.join(' '),
  ocorrencias.join(' '),
  pendencias.join(' ')
].join(' ');

const textoGeral = textoGeralOriginal.toLowerCase();

// Prioriza data explícita na mensagem, por exemplo 08/06/2026
const dataExtraidaTexto = extractDateBR(textoGeralOriginal);
const data_rdo = dataExtraidaTexto || formatDate(input.data_rdo);

const temPendenciaPorTexto =
  textoGeral.includes('não foram enviadas fotos') ||
  textoGeral.includes('nao foram enviadas fotos') ||
  textoGeral.includes('sem fotos') ||
  textoGeral.includes('necessário') ||
  textoGeral.includes('necessario') ||
  textoGeral.includes('pendência') ||
  textoGeral.includes('pendencia') ||
  textoGeral.includes('confirmar') ||
  textoGeral.includes('conferir');

// Se detectou pendência no texto, mas a lista pendencias está vazia,
// cria uma pendência real.
if (pendencias.length === 0 && temPendenciaPorTexto) {
  if (
    textoGeral.includes('não foram enviadas fotos') ||
    textoGeral.includes('nao foram enviadas fotos') ||
    textoGeral.includes('sem fotos')
  ) {
    pendencias.push('Não foram enviadas fotos da execução.');
  } else {
    pendencias.push('Há informações pendentes ou incompletas no RDO.');
  }
}

const possui_pendencias = pendencias.length > 0;

const status_rdo = possui_pendencias
  ? 'PENDENTE_REVISAO'
  : 'MINUTA_GERADA';

const resumo_executivo =
  `No dia ${data_rdo || 'não informado'}, foram registradas atividades na obra ${obra_codigo || 'não informada'}, sob responsabilidade de ${responsavel || 'responsável não informado'}. ` +
  `As principais atividades relatadas foram: ${atividades.join('; ') || 'não informadas'}.`;

const observacoes_tecnicas =
  ocorrencias.length > 0
    ? `Foram registradas as seguintes ocorrências: ${ocorrencias.join('; ')}.`
    : 'Não foram registradas ocorrências relevantes no período.';

const recomendacoes =
  possui_pendencias
    ? `Recomenda-se revisar as pendências apontadas antes da validação final do RDO: ${pendencias.join('; ')}.`
    : 'RDO apto para revisão e validação pelo responsável técnico.';

return [
  {
    json: {
      obra_codigo,
      data_rdo,
      responsavel,

      clima,
      condicoes_canteiro,

      atividades_executadas: atividades,
      mao_de_obra: maoDeObra,
      equipamentos,
      materiais_recebidos: materiais,
      ocorrencias,
      pendencias,

      idempotency_key: item.idempotency_key || null,
      correlation_id: item.correlation_id || null

      resumo_executivo,
      observacoes_tecnicas,
      recomendacoes,

      status_rdo,
      possui_pendencias,

      origem: cleanText(input.origem) || 'WEBHOOK',

      payload_original: {
        entrada_original: inputOriginal,
        entrada_normalizada: input
      },

      agente_nome: 'Agente Gerador de Diário de Obra',
      agente_versao: '0.1.0',
      modo_processamento: 'MOCK',
      data_processamento: new Date().toISOString()
    }
  }
];

 const item = $input.first().json;

function cleanText(value) {
  if (value === undefined || value === null) return '';
  return String(value).replace(/^=/, '').trim();
}

function parseBoolean(value) {
  if (value === true) return true;
  if (value === false) return false;

  if (value === undefined || value === null || value === '') return false;

  const text = String(value).trim().toLowerCase();

  if (['true', 't', '1', 'sim', 'yes'].includes(text)) return true;
  if (['false', 'f', '0', 'nao', 'não', 'no'].includes(text)) return false;

  return false;
}

function asArray(value) {
  if (value === undefined || value === null || value === '') return [];

  if (Array.isArray(value)) {
    return value.map(cleanText).filter(Boolean);
  }

  if (typeof value === 'object') {
    if (Array.isArray(value.itens)) {
      return value.itens.map(cleanText).filter(Boolean);
    }

    return Object.keys(value).length > 0 ? [JSON.stringify(value)] : [];
  }

  const text = cleanText(value);

  if (!text) return [];

  try {
    const parsed = JSON.parse(text);

    if (Array.isArray(parsed)) {
      return parsed.map(cleanText).filter(Boolean);
    }

    if (parsed && typeof parsed === 'object' && Array.isArray(parsed.itens)) {
      return parsed.itens.map(cleanText).filter(Boolean);
    }

    if (parsed && typeof parsed === 'object') {
      return Object.keys(parsed).length > 0 ? [JSON.stringify(parsed)] : [];
    }

    return [cleanText(parsed)].filter(Boolean);
  } catch (error) {
    return text
      .split(/;|\n/)
      .map(v => cleanText(v))
      .filter(Boolean);
  }
}

function jsonbObject(value) {
  return {
    itens: asArray(value)
  };
}

function safeObject(value) {
  if (!value) return {};

  if (typeof value === 'object') return value;

  try {
    return JSON.parse(value);
  } catch (error) {
    return {
      valor_original: String(value)
    };
  }
}

function formatDate(value) {
  if (!value) {
    return new Date().toISOString().slice(0, 10);
  }

  const cleaned = cleanText(value);

  if (/^\d{4}-\d{2}-\d{2}$/.test(cleaned)) {
    return cleaned;
  }

  const date = new Date(cleaned);

  if (!isNaN(date.getTime())) {
    return date.toISOString().slice(0, 10);
  }

  return new Date().toISOString().slice(0, 10);
}

const pendenciasArray = asArray(item.pendencias);
const ocorrenciasArray = asArray(item.ocorrencias);

const possuiPendenciasReal = parseBoolean(item.possui_pendencias);

const statusRdoReal = possuiPendenciasReal
  ? 'PENDENTE_REVISAO'
