return [
  {
    json: {
      obra_codigo: cleanText(item.obra_codigo) || null,
      data_rdo: formatDate(item.data_rdo),
      responsavel: cleanText(item.responsavel) || null,

      idempotency_key: item.idempotency_key || null,
      correlation_id: item.correlation_id || null

      clima: cleanText(item.clima) || null,
      condicoes_canteiro: cleanText(item.condicoes_canteiro) || 'Não informado.',

      atividades_executadas: jsonbObject(item.atividades_executadas),
      mao_de_obra: jsonbObject(item.mao_de_obra),
      equipamentos: jsonbObject(item.equipamentos),
      materiais_recebidos: jsonbObject(item.materiais_recebidos),
      ocorrencias: {
        itens: ocorrenciasArray
      },
      pendencias: {
        itens: pendenciasArray
      },

      resumo_executivo: cleanText(item.resumo_executivo) || null,
      observacoes_tecnicas: cleanText(item.observacoes_tecnicas) || null,
      recomendacoes: cleanText(item.recomendacoes) || null,

      status_rdo: statusRdoReal,
      possui_pendencias: possuiPendenciasReal,
      acionar_agente_03: possuiPendenciasReal,

      origem: cleanText(item.origem) || 'WEBHOOK',

      payload_original: safeObject(item.payload_original),

      agente_nome: cleanText(item.agente_nome) || 'Agente Gerador de Diário de Obra',
      agente_versao: cleanText(item.agente_versao) || '0.1.0',
      modo_processamento: cleanText(item.modo_processamento) || 'MOCK',

      data_processamento: item.data_processamento || new Date().toISOString()
    }
  }
];

