const rdo = $input.first().json;

function parseBoolean(value) {
  if (value === true) return true;
  if (value === false) return false;

  return ['true', 't', '1', 'sim', 'yes'].includes(
    String(value ?? '').trim().toLowerCase()
  );
}

function hasItems(value) {
  if (!value) return false;

  if (Array.isArray(value)) {
    return value.length > 0;
  }

  if (typeof value === 'object') {
    if (Array.isArray(value.itens)) {
      return value.itens.length > 0;
    }

    return Object.keys(value).length > 0;
  }

  try {
    const parsed = JSON.parse(value);

    if (Array.isArray(parsed)) {
      return parsed.length > 0;
    }

    if (parsed && Array.isArray(parsed.itens)) {
      return parsed.itens.length > 0;
    }
  } catch (error) {
    return String(value).trim().length > 0;
  }

  return false;
}

const possuiPendencias =
  parseBoolean(rdo.possui_pendencias) ||
  rdo.status_rdo === 'PENDENTE_REVISAO' ||
  hasItems(rdo.pendencias) ||
  hasItems(rdo.ocorrencias);

return [
  {
    json: {
      ...rdo,

      possui_pendencias: possuiPendencias,
      acionar_agente_03: possuiPendencias,

      status_rdo: possuiPendencias
        ? 'PENDENTE_REVISAO'
        : 'MINUTA_GERADA'
    }
  }
];
